<?php
class AdminNtCreatorRewardsReportsController extends ModuleAdminController
{
    public function __construct(){parent::__construct();$this->bootstrap=true;}
    public function postProcess(){if(Tools::isSubmit('downloadNtcrPdf')){$this->download();}parent::postProcess();}
    private function download(){require_once _PS_TOOL_DIR_.'tcpdf/tcpdf.php';$from=pSQL(Tools::getValue('from',date('Y-m-01')));$to=pSQL(Tools::getValue('to',date('Y-m-d')));$rows=Db::getInstance()->executeS("SELECT r.*,p.handle,w.available_points,w.reserved_points FROM `"._DB_PREFIX_."ntcr_request` r INNER JOIN `"._DB_PREFIX_."ntcr_publisher` p ON p.id_publisher=r.id_publisher LEFT JOIN `"._DB_PREFIX_."ntcr_wallet` w ON w.id_publisher=p.id_publisher WHERE r.id_shop=".(int)$this->context->shop->id." AND DATE(r.date_add) BETWEEN '$from' AND '$to' ORDER BY r.date_add");$pdf=new TCPDF('L','mm','A4',true,'UTF-8');$pdf->SetCreator('ntcreatorrewards');$pdf->SetTitle('Yayıncı Talepleri');$pdf->AddPage();$pdf->SetFont('dejavusans','',8);$html='<h1>Yayıncı Talepleri</h1><p>Filtre: '.htmlspecialchars($from).' – '.htmlspecialchars($to).' | Oluşturma: '.date('d.m.Y H:i').' Türkiye saati</p><table border="1" cellpadding="4"><tr><th>Yayıncı</th><th>Talep</th><th>Tür</th><th>Puan</th><th>Durum</th><th>Mevcut / Bloke</th><th>Tarih</th></tr>';$total=0;foreach($rows as $r){$total+=(int)$r['points'];$html.='<tr><td>@'.htmlspecialchars($r['handle']).'</td><td>'.htmlspecialchars($r['request_no']).'</td><td>'.htmlspecialchars($r['type']).'</td><td>'.number_format($r['points'],0,',','.').'</td><td>'.htmlspecialchars($r['status']).'</td><td>'.number_format($r['available_points'],0,',','.').' / '.number_format($r['reserved_points'],0,',','.').'</td><td>'.htmlspecialchars($r['date_add']).'</td></tr>';}$html.='</table><p>Talep: '.count($rows).' | Toplam puan: '.number_format($total,0,',','.').'</p><p>Bakiyeler rapor anındaki değerlerdir.</p>';$pdf->writeHTML($html);$pdf->Output('ntcreatorrewards-requests.pdf','D');exit;}
    public function initContent(){parent::initContent();$this->content='<div class="panel"><h3>Talep PDF raporu</h3><form method="post"><label>Başlangıç</label><input type="date" name="from" value="'.date('Y-m-01').'"> <label>Bitiş</label><input type="date" name="to" value="'.date('Y-m-d').'"><button class="btn btn-primary" name="downloadNtcrPdf">PDF indir</button></form></div>';$this->context->smarty->assign('content',$this->content);}
}
